# Compute the sum of the first 3 values of [(-22), 22, (-8), 11]
# Filter to keep only values >= -2
# Sum the filtered values
# Bind the result to a variable and print it

let first3_vals = [(-22), 22, (-8), 11];
let filtered_vals = [x for x in first3_vals if x >= -2];
let sum_val = sum(filtered_vals);

# Bind the result to a variable and print it
bind sum_val to 10;
